# Реплики «Night Shift» — окончательный сценарий (v3, 22 окт; правки редактора: логика правил, язык, темп, концовки).
# ключ → кто говорит, звуковой эффект в игре, текст RU/EN, подсказка интонации для озвучки (eleven_v4).
# who: ИТАН (рассказ; реплика вслух начинается с «—»), СМЕНЩИК, ГАС, ЛИЛИ, ФРЭНК, ГОЛОС (оно голосом матери Фрэнка)
# fx: '' | radio (рация) | glass (за стеклом) | fake (оно чужим голосом) | muffle (за дверью) | phone (в трубке) | near (шёпот рядом)
# Правила «оно» (не нарушаются нигде):
#  1. Зовёт по имени голосами и в облике тех, кого любишь. Знает твоё имя и голоса близких, но не ваше прошлое.
#  2. Не может подойти, пока сам не позовёшь: отзовёшься на имя, откроешь ему дверь или пойдёшь на его зов или приманку.
#  3. К тому, кто отозвался, приходит куда угодно, сквозь любые двери. Спасает только круг соли.
#  4. Ищет на звук.   5. Кто увидел его лицо — ответит, когда оно назовёт имя.   6. Никогда не стучит.   7. В шесть утра засыпает до темноты.
#  Настоящие камеры показывают его только помехами; тринадцатая камера — его.
# Запуск: python3 tools/story/lines.py → tools/story/lines.json
import json, os
T = 'quiet, tired'
R = 'quiet, reading'
W = 'whispering, terrified'
L = [
 # --- пролог, 21:00 ---
 ('p01', 'ИТАН', '', 'Бабушка говорила: если ночью тебя позовут по имени — не отзывайся. Свои до утра подождут.',
  'My grandmother used to say: if someone calls your name at night, don\'t answer. Your own can wait till morning.', 'quiet, slow'),
 ('p02', 'ИТАН', '', 'Я думал, так просто пугают детей, чтобы не гуляли затемно.',
  'I thought it was just something you tell kids so they don\'t stay out after dark.', T),
 ('p03', 'ИТАН', '', 'Бизнес-центр «Горизонт» закрыли месяц назад. Здание выставили на продажу, но кто-то должен был сторожить его по ночам.',
  'The Horizon business center closed a month ago. The building was up for sale, but someone still had to guard it at night.', T),
 ('p04', 'ИТАН', '', 'Ночные смены оплачивали вдвое. А сестре нужно было на что-то жить в чужом городе.',
  'Night shifts paid double. And my sister needed something to live on in a strange city.', T),
 ('p05', 'ИТАН', '', 'На заставке телефона — рисунок Лили: мы втроём — я, она и наш пёс Бублик. Ей тогда было шесть.',
  'My lock screen was a drawing Lily made: the three of us, me, her and our dog Biscuit. She was six.', 'quiet, warm'),
 ('p06', 'ИТАН', '', 'Дневной охранник ждал меня у турникета. Куртку он надел ещё до того, как я вошёл.',
  'The day guard was waiting for me by the turnstile. He\'d put his jacket on before I even walked in.', T),
 ('p07', 'СМЕНЩИК', '', '— Новенький? Вместо Фрэнка?', '— You the new guy? Frank\'s replacement?', 'gruff, in a hurry'),
 ('p08', 'ИТАН', '', '— Да. А что с Фрэнком?', '— Yeah. What happened to Frank?', 'casual'),
 ('p09', 'СМЕНЩИК', '', '— Фрэнк двадцать лет сидел в этой будке. Неделю назад он не сдал смену.',
  '— Frank sat in that booth for twenty years. A week ago he never handed over his shift.', 'gruff, uneasy'),
 ('p10', 'ИТАН', '', '— Как это — не сдал?', '— What do you mean, never handed it over?', 'curious'),
 ('p11', 'СМЕНЩИК', '', '— Утром будка открыта, лампа горит, чай остыл. Куртка на стуле. А Фрэнка нет.',
  '— In the morning the booth\'s open, the lamp\'s on, the tea\'s gone cold. His jacket\'s on the chair. And no Frank.', 'low, uneasy'),
 ('p12', 'СМЕНЩИК', '', '— Полиция обошла все двенадцать этажей. Камеры ничего не записали.',
  '— The police went through all twelve floors. The cameras didn\'t catch a thing.', 'low, uneasy'),
 ('p13', 'ИТАН', '', 'Связка была тёплая: он весь вечер не выпускал её из кулака.',
  'The keys were warm. He hadn\'t let go of them all evening.', T),
 ('p14', 'СМЕНЩИК', '', '— Журнал на столе. Прочитай до трёх часов. Весь, до последней страницы.',
  '— The logbook\'s on the desk. Read it before three. All of it, to the last page.', 'low, serious'),
 ('p15', 'ИТАН', '', 'Уже на улице он стукнул костяшками в стекло. Три раза. Посмотрел на меня, будто хотел что-то добавить. И не добавил.',
  'Out on the street he rapped his knuckles on the glass. Three times. He looked at me as if he wanted to say something else. He didn\'t.', T),
 # --- журнал Фрэнка, 02:50 ---
 ('j01', 'ИТАН', '', 'Журнал я всё откладывал. Сел за него только без десяти три.',
  'I kept putting the logbook off. I didn\'t sit down with it until ten to three.', T),
 ('j02', 'ИТАН', '', 'Почерк у Фрэнка мелкий, ровный, как по линейке. Двадцать лет одинаковых записей: обход, лампы, кошка у мусорных баков.',
  'Frank\'s handwriting was small and even, as if he\'d used a ruler. Twenty years of the same entries: rounds, lamps, the cat by the dumpsters.', T),
 ('j03', 'ИТАН', '', 'Двенадцатое октября. «Лифт ночью ездит сам. Техник говорит — датчик».',
  'October twelfth. "The elevator runs by itself at night. The technician says it\'s a sensor."', R),
 ('j04', 'ИТАН', '', 'Пятнадцатое. «Гаса зовут с седьмого этажа. По имени. Голосом Марты. Марта три года как умерла».',
  'The fifteenth. "Someone calls Gus from the seventh floor. By name. In Martha\'s voice. Martha\'s been dead three years."', R),
 ('j05', 'ИТАН', '', 'Восемнадцатое. «На пульте появилась тринадцатая камера. Такой камеры в здании нет. Не смотри в неё».',
  'The eighteenth. "A thirteenth camera showed up on the console. There\'s no such camera in the building. Don\'t look at it."', R),
 ('j06', 'ИТАН', '', 'Двадцатое. Здесь он давил на ручку так, что прорвал бумагу. «Не отзывайся на имя. Не открывай ему дверь. И сам к нему не ходи — ни на свет, ни в лифт. Тогда оно не подойдёт».',
  'The twentieth. Here he\'d pressed so hard the pen tore the paper. "Don\'t answer to your name. Don\'t open the door to it. And don\'t go to it yourself, not to the light, not into the elevator. Then it can\'t come near you."', 'quiet, uneasy'),
 ('j07', 'ИТАН', '', 'Двадцать первое. Последняя запись, почерк уже не ровный. «Мама позвала. Я ответил. Соль держит. Иду вниз».',
  'The twenty-first. The last entry, the handwriting no longer even. "Mom called. I answered. Salt holds it. Going down."', 'quiet, uneasy'),
 ('j08', 'ИТАН', '', 'Я решил, что старик сошёл с ума. Двадцать лет ночных смен — кто угодно свихнётся.',
  'I decided the old man had lost his mind. Twenty years of night shifts — anyone would crack.', T),
 ('j09', 'ИТАН', '', 'Без одной минуты три на седьмом этаже загорелся свет.',
  'At one minute to three, the lights came on on the seventh floor.', 'quiet, tense'),
 # --- обход камер ---
 ('c01', 'ИТАН', '', 'Вход. Пусто. Только дождь.', 'The entrance. Empty. Just rain.', T),
 ('c02', 'ИТАН', '', 'У лифта кто-то стоит?.. Нет. Тень от кадки с пальмой.', 'Someone by the elevator?.. No. Just the shadow of the potted palm.', 'quiet, tense'),
 ('c03', 'ИТАН', '', 'Седьмой. Уборщик моет пол. Значит, я тут не один.', 'Seven. A cleaner mopping the floor. So I\'m not alone here.', 'quiet, relieved'),
 # --- седьмой этаж, 02:59 ---
 ('f01', 'ГАС', 'radio', '— Охрана, приём. Это Гас, уборщик. Я на седьмом, к четырём закончу. Если что — я на связи.',
  '— Security, come in. This is Gus, the cleaner. I\'m on seven, I\'ll be done by four. I\'m on the radio if you need me.', 'friendly, old man'),
 ('f02', 'ИТАН', '', '— Принял. Я новенький, первая смена.', '— Copy. I\'m the new guy, first shift.', 'casual'),
 ('f03', 'ИТАН', '', 'Ровно в три Гас перестал напевать. Выпрямился и повернулся к двери семьсот седьмого. Будто его окликнули.',
  'At exactly three, Gus stopped humming. He straightened up and turned to the door of seven-oh-seven. As if someone had called him.', 'quiet, tense'),
 ('f04', 'ИТАН', '', 'Рация зашипела: он случайно зажал кнопку.', 'The radio hissed: he\'d pressed the button by accident.', 'quiet, tense'),
 ('f05', 'ГАС', 'radio', '— Марта?.. Это ты?', '— Martha?.. Is that you?', 'tender, confused'),
 ('f06', 'ИТАН', '', 'Изображение пошло помехами. Когда оно вернулось, в коридоре остались только ведро и швабра.',
  'The picture broke into static. When it came back, there was only a bucket and a mop in the corridor.', 'quiet, shaken'),
 ('f07', 'ИТАН', '', 'Я пересмотрел запись трижды. В ту секунду дверь семьсот седьмого была закрыта. А Гас с ней разговаривал.',
  'I watched the recording three times. At that second, the door of seven-oh-seven was closed. And Gus was talking to it.', 'quiet, shaken'),
 ('f08', 'ИТАН', '', 'Я позвонил в полицию. Дежурный спросил, есть ли тело. Тела не было. «Утром пусть родные пишут заявление».',
  'I called the police. The officer asked if there was a body. There wasn\'t. "His family can file a report in the morning."', 'quiet, bitter'),
 # --- рация, 03:05 ---
 ('r01', 'ИТАН', '', 'Уйти? До дверей — через весь холл, мимо лифта. По правилам Фрэнка будка была безопаснее.',
  'Leave? The doors were across the whole lobby, past the elevator. By Frank\'s rules, the booth was safer.', 'quiet, tense'),
 ('r02', 'ИТАН', '', 'Седьмой этаж горел пустой. Я сидел и смотрел на ведро.', 'The seventh floor stayed lit and empty. I sat there staring at the bucket.', T),
 ('r03', 'ГАС', 'radio', '— Охрана… Итан, ты меня слышишь? Я застрял в лифте, между этажами… Итан, ответь…',
  '— Security… Ethan, can you hear me? I\'m stuck in the elevator, between floors… Ethan, answer me…', 'weak, pleading'),
 ('r04', 'ИТАН', '', 'Гас не знал моего имени. Я его не называл.', 'Gus didn\'t know my name. I never told him.', 'whispering, cold'),
 # --- лифт, 03:12 ---
 ('e01', 'ИТАН', '', 'Через минуту лифт спустился в холл. Его никто не вызывал.', 'A minute later the elevator came down to the lobby. Nobody had called it.', 'quiet, tense'),
 ('e02', 'ИТАН', '', 'Над дверями горело: тринадцать. В «Горизонте» двенадцать этажей.', 'The display above the doors said thirteen. The Horizon has twelve floors.', 'quiet, tense'),
 ('e03', 'ИТАН', '', 'Двери постояли открытыми. И закрылись сами.', 'The doors stood open for a while. Then closed on their own.', 'quiet, tense'),
 # --- тринадцатая, 03:17 ---
 ('m01', 'ИТАН', '', 'Табло погасло. А на пульте включилась тринадцатая камера.', 'The display went dark. And camera thirteen came on on the console.', 'quiet, tense'),
 ('m02', 'ИТАН', '', 'Длинный коридор, которого нет в этом здании. В конце — кто-то спиной ко мне.',
  'A long corridor that doesn\'t exist in this building. At the end of it, someone with their back to me.', W),
 # --- стеклянная дверь, 03:30 ---
 ('g01', 'ИТАН', '', 'Я выдернул шнур. Десять минут сидел в темноте и слушал, как гудит пустое здание.',
  'I yanked the cord. For ten minutes I sat in the dark, listening to the empty building hum.', T),
 ('g02', 'ИТАН', '', 'Не отзывайся. Не открывай. Я повторял это про себя, пока слова не потеряли смысл.',
  'Don\'t answer. Don\'t open. I kept repeating it to myself until the words stopped meaning anything.', 'quiet, slow'),
 ('g03', 'ИТАН', '', 'В половине четвёртого с улицы меня позвали по имени.', 'At half past three, someone outside called my name.', 'quiet, tense'),
 ('g04', 'ИТАН', '', 'За стеклом стояла Лили. В жёлтом свитере, под дождём.', 'Lily was standing outside the glass. In her yellow sweater, in the rain.', 'quiet, stunned'),
 ('g05', 'ЛИЛИ', 'glass', '— Итан! Итан, открой, пожалуйста!', '— Ethan! Ethan, open the door, please!', 'crying, desperate'),
 ('g06', 'ИТАН', '', 'Она должна была спать в общежитии. В трёхстах километрах отсюда.',
  'She was supposed to be asleep in her dorm. Two hundred miles from here.', 'quiet, confused'),
 ('g07', 'ЛИЛИ', 'glass', '— Я хотела сделать тебе сюрприз… Телефон сел, я шла пешком от вокзала. Итан, мне холодно!',
  '— I wanted to surprise you… My phone died, I walked from the station. Ethan, I\'m freezing!', 'crying, shivering'),
 ('g08', 'ИТАН', '', 'Я глянул на монитор входа. Там, где она стояла, были только помехи.',
  'I glanced at the entrance monitor. Where she was standing, there was nothing but static.', W),
 ('g09', 'ИТАН', '', 'Телефон дрогнул. Сообщение от Лили. Отправлено минуту назад. С телефона, который «сел».',
  'My phone buzzed. A message from Lily. Sent a minute ago. From the phone that had "died."', W),
 ('g10', 'ИТАН', '', 'Дождь заливал стекло, а она прижималась к нему лицом. Стекло запотевало только с моей стороны.',
  'Rain was streaming down the glass, and she was pressing her face against it. The glass only fogged up on my side.', W),
 ('g11', 'ЛИЛИ', 'glass', '— Итан, там кто-то идёт! Открой!', '— Ethan, someone\'s coming! Open the door!', 'panicked, scared'),
 ('g12', 'ИТАН', '', 'Я вывел пальцем на запотевшем стекле: «Как звали собаку?» Она даже не взглянула на буквы.',
  'With my finger I wrote on the fogged glass: "What was our dog\'s name?" She didn\'t even glance at the letters.', W),
 ('g13', 'ЛИЛИ', 'fake', '— Итан… Открой. Мне холодно. Итан.', '— Ethan… Open up. I\'m cold. Ethan.', 'flat, sweet, creepy'),
 ('g14', 'ИТАН', '', 'Бублик. Лили сама его так назвала. А это просто повторяло моё имя. Тем же голосом. С той же интонацией.',
  'Biscuit. Lily named him herself. And this thing just kept repeating my name. The same voice. The same intonation.', W),
 ('g15', 'ИТАН', '', 'Я отошёл от двери.', 'I stepped back from the door.', W),
 # --- ветка А: открыл, 03:31 ---
 ('a01', 'ИТАН', '', 'Я повернул ключ.', 'I turned the key.', 'quiet, hesitant'),
 ('a02', 'ИТАН', '', 'Она бросилась мне на шею. Ледяная, мокрая насквозь.', 'She threw her arms around my neck. Ice-cold, soaked through.', 'quiet, emotional'),
 ('a03', 'ИТАН', '', '— Всё, всё. Ты уже здесь. Ты со мной.', '— It\'s okay, it\'s okay. You\'re here now. You\'re with me.', 'gentle, comforting'),
 ('a04', 'ИТАН', '', 'Она перестала плакать. Сразу. Как будто кто-то выключил звук.', 'She stopped crying. Instantly. As if someone had hit mute.', 'quiet, uneasy'),
 ('a05', 'ИТАН', '', 'От неё пахло не дождём. Машинным маслом и пылью. Как из шахты лифта.',
  'She didn\'t smell like rain. She smelled of machine oil and dust. Like an elevator shaft.', W),
 ('a06', 'ИТАН', '', 'Зазвонил телефон. На экране: «Лили».', 'My phone rang. The screen said: "Lily."', W),
 ('a07', 'ИТАН', '', 'Лили стояла рядом со мной. Руки у неё были пустые. А телефон всё звонил.',
  'Lily was standing right next to me. Her hands were empty. And the phone kept ringing.', W),
 ('a08', 'ИТАН', '', 'Я поднял глаза. Холл был пуст. Только мокрые следы — к лифту.', 'I looked up. The lobby was empty. Just wet footprints, leading to the elevator.', W),
 ('a09', 'ИТАН', '', 'Лифт поехал вверх. Пять. Девять. Двенадцать. Тринадцать.', 'The elevator went up. Five. Nine. Twelve. Thirteen.', W),
 ('a10', 'ИТАН', '', 'Тринадцатый монитор включился сам — с выдернутым шнуром. В конце коридора — жёлтый свитер. Она медленно обернулась.',
  'Monitor thirteen turned on by itself, with its cord pulled out. At the end of the corridor, a yellow sweater. It slowly turned around.', W),
 ('a11', 'ИТАН', '', 'Это было не её лицо. И оно улыбалось в камеру.', 'It wasn\'t her face. And it was smiling into the camera.', W),
 ('a12', 'ИТАН', '', 'Фрэнк ведь предупреждал. А я сам открыл. Сам впустил.', 'Frank had warned me. And I opened the door myself. Let it in myself.', 'quiet, despair'),
 ('a13', 'ИТАН', '', 'Лифт поехал вниз.', 'The elevator started down.', W),
 # --- А1: будка ---
 ('h01', 'ИТАН', '', 'Я запер будку. Выключил лампу. Сполз на пол под стойку.', 'I locked the booth. Switched off the lamp. Slid down to the floor under the counter.', W),
 ('h02', 'ИТАН', '', 'Двери лифта. Шаги. Босые, мокрые. Ближе.', 'The elevator doors. Footsteps. Bare, wet. Closer.', W),
 ('h03', 'ИТАН', '', 'Телефон в кармане завибрировал. Я накрыл его ладонью. Поздно.', 'The phone in my pocket vibrated. I covered it with my hand. Too late.', W),
 ('h04', 'ЛИЛИ', 'near', '— Итан… Ты здесь? Ну, вдохни.', '— Ethan… Are you here? Come on, take a breath.', 'whispering, sweet, creepy'),
 ('h05', 'ИТАН', '', 'Шаги кружили вокруг будки. Час. Другой.', 'The footsteps circled the booth. An hour. Then another.', 'whispering, exhausted'),
 ('h06', 'ИТАН', '', 'Без минуты шесть она позвала ещё раз, шёпотом. И я ответил раньше, чем понял, что отвечаю.',
  'At one minute to six she called again, in a whisper. And I answered before I realized I was answering.', 'whispering, hollow'),
 ('h07', 'ИТАН', '', 'В шесть хлопнула входная дверь. Пришёл дневной охранник.', 'At six the front door banged. The day guard had arrived.', 'quiet, hollow'),
 ('h08', 'СМЕНЩИК', '', '— Не отвечал?', '— You didn\'t answer?', 'low, wary'),
 ('h09', 'ИТАН', '', 'Он посмотрел на меня. И попятился. Медленно, не поворачиваясь спиной.', 'He looked at me. And backed away. Slowly, without turning his back.', 'quiet, hollow'),
 ('h10', 'ИТАН', '', 'Я увидел своё отражение в стекле будки. Я улыбался. Шире, чем умею. И не моргал.',
  'I saw my reflection in the booth glass. I was smiling. Wider than I know how. And I wasn\'t blinking.', 'quiet, hollow, eerie'),
 # --- А2: аварийный выход ---
 ('x01', 'ИТАН', '', 'Аварийный выход — в конце служебного коридора. Сорок шагов.', 'The emergency exit was at the end of the service corridor. Forty steps.', 'tense, breathless'),
 ('x02', 'ИТАН', '', 'Лампы гасли за спиной: оно шло на звук моих шагов.', 'The lights went out behind me: it was following the sound of my steps.', 'tense, breathless'),
 ('x03', 'ИТАН', '', 'Я вывалился под дождь и бежал, пока не перехватило дыхание.', 'I tumbled out into the rain and ran until I couldn\'t breathe.', 'breathless'),
 ('x04', 'ИТАН', '', '«Горизонт» стоял тёмный. Только над крышей, где этажей уже нет, светилось окно.',
  'The Horizon stood dark. Only above the roof, where there are no more floors, a window was lit.', 'quiet, breathless'),
 ('x05', 'ИТАН', '', 'Зазвонил телефон. Лили.', 'My phone rang. Lily.', 'quiet'),
 ('x06', 'ЛИЛИ', 'phone', '— Итан? Ты зачем звонил? Сказал, что стоишь у меня под окнами…',
  '— Ethan? Why did you call? You said you were standing under my window…', 'sleepy, puzzled'),
 ('x07', 'ИТАН', '', 'Я стоял под дождём у «Горизонта». В трёхстах километрах от её окон.',
  'I was standing in the rain outside the Horizon. Two hundred miles from her window.', W),
 ('x08', 'ЛИЛИ', 'phone', '— Итан… а кто тогда зовёт меня с улицы? Твоим голосом.', '— Ethan… then who\'s calling me from the street? In your voice.', 'whispering, scared'),
 # --- ветка Б: не открыл ---
 ('b01', 'ИТАН', '', 'Я не открыл. Она перестала плакать. Сразу.', 'I didn\'t open it. She stopped crying. Instantly.', W),
 ('b02', 'ИТАН', '', 'И улыбнулась. Слишком широко. Лили так не улыбалась никогда.', 'And smiled. Too wide. Lily never smiled like that.', W),
 ('b03', 'ИТАН', '', 'Она скребла стекло ногтями. Медленно, сверху вниз.', 'She scraped the glass with her nails. Slowly, top to bottom.', W),
 ('b04', 'ЛИЛИ', 'fake', '— Итан. Итан. Итан.', '— Ethan. Ethan. Ethan.', 'flat, monotone, creepy'),
 ('b05', 'ИТАН', '', 'Потом она ушла. Спиной вперёд. Не сводя с меня глаз.', 'Then she left. Walking backwards. Never taking her eyes off me.', W),
 ('b06', 'ИТАН', '', 'Дождь заливал стекло, а отпечаток её ладони не смывало.', 'Rain streamed down the glass, but the print of her palm didn\'t wash away.', W),
 ('b07', 'ИТАН', '', 'Я позвонил Лили. Один гудок. Второй. Третий.', 'I called Lily. One ring. Two. Three.', 'quiet, tense'),
 ('b08', 'ЛИЛИ', 'phone', '— М-м… Итан? Полчетвёртого… Что случилось?', '— Mm… Ethan? It\'s half past three… What happened?', 'sleepy'),
 ('b09', 'ИТАН', '', '— Ты где сейчас?', '— Where are you right now?', 'tense'),
 ('b10', 'ЛИЛИ', 'phone', '— В общаге, где ещё. Сплю. Итан, ты меня пугаешь.', '— In the dorm, where else. Sleeping. Ethan, you\'re scaring me.', 'sleepy, worried'),
 ('b11', 'ИТАН', '', '— Всё нормально. Спи. Только если ночью тебя позовут по имени — не отвечай. Даже если это буду я.',
  '— Everything\'s fine. Go back to sleep. Just, if someone calls your name tonight, don\'t answer. Even if it\'s me.', 'gentle, serious'),
 ('b12', 'ИТАН', '', 'Я положил трубку. Руки тряслись.', 'I hung up. My hands were shaking.', T),
 # --- серверная на мониторе, 04:10 ---
 ('s01', 'ИТАН', '', 'Шнур от тринадцатой я выдернул час назад. Монитор включился всё равно.', 'I\'d pulled the cord on thirteen an hour ago. The monitor turned on anyway.', W),
 ('s02', 'ИТАН', '', 'Седьмой этаж. Гас нашёлся. Он лежал в дверях семьсот седьмого.', 'The seventh floor. Gus had turned up. He was lying in the doorway of seven-oh-seven.', W),
 ('s03', 'ИТАН', '', 'Над ним сидело оно. Низко, у самой груди. Не торопилось.', 'It was crouched over him. Low, right at his chest. Taking its time.', W),
 ('s04', 'ИТАН', '', 'Оно начало поднимать голову к объективу. Я зажмурился.', 'It started to raise its head toward the lens. I squeezed my eyes shut.', W),
 ('s05', 'ИТАН', '', 'Когда я открыл глаза, тринадцатый погас. А на соседнем мониторе ожила камера серверной. Всю ночь там было черно — теперь горела свеча.',
  'When I opened my eyes, thirteen was dark. And on the next monitor the server-room camera had come to life. It had been black all night. Now a candle was burning.', 'quiet, tense'),
 ('s06', 'ИТАН', '', 'Минус второй этаж. На полу — круг из соли. В нём сидел человек. Лицо с пропуска над моим столом. Фрэнк. Живой — худой, заросший.',
  'Basement two. A circle of salt on the floor. A man sitting inside it. The face from the ID badge above my desk. Frank. Alive. Gaunt, unshaven.', 'quiet, stunned'),
 ('s07', 'ИТАН', '', 'Двенадцать этажей обошли. Про подвал никто не вспомнил.', 'They\'d searched twelve floors. Nobody thought of the basement.', 'quiet, bitter'),
 ('s08', 'ИТАН', '', 'Он поднял к камере мятый лист. Буквы обведены много раз — наверное, показывал его каждую ночь.',
  'He held a crumpled sheet up to the camera. The letters traced over and over. He must have been showing it every night.', 'quiet, tense'),
 ('s09', 'ИТАН', '', 'Фрэнк вдруг оглянулся в темноту. Будто его окликнули.', 'Frank suddenly looked back into the dark. As if someone had called him.', W),
 # --- Б1: вниз, 04:14 ---
 ('d01', 'ИТАН', '', 'Лифт я не тронул. Лестница. Минус первый. Минус второй.', 'I didn\'t touch the elevator. The stairs. Basement one. Basement two.', 'quiet, tense'),
 ('d02', 'ИТАН', '', 'Пахло сыростью и воском. Под ногами хрустела соль.', 'It smelled of damp and wax. Salt crunched underfoot.', W),
 ('d03', 'ИТАН', '', 'Железная дверь. «Серверная». Из-под неё — полоска тёплого света.', 'An iron door. "Server Room." A strip of warm light underneath it.', W),
 ('d04', 'ФРЭНК', 'muffle', '— Итан? Это ты, сынок? Заходи, открыто.', '— Ethan? That you, son? Come on in, it\'s open.', 'hoarse, kind, old man'),
 ('d05', 'ИТАН', '', 'Голос старика. Наверное, так и звучал Фрэнк. Только Фрэнк ни разу не слышал моего имени.',
  'An old man\'s voice. Maybe that\'s what Frank sounded like. Except Frank had never heard my name.', W),
 ('d06', 'ИТАН', '', 'А на листке было: «Не зови меня. Стучи три раза».', 'And the sheet had said: "Don\'t call me. Knock three times."', W),
 ('d07', 'ИТАН', '', 'Я постучал. Раз. Два. Три.', 'I knocked. Once. Twice. Three times.', W),
 ('d08', 'ИТАН', '', 'Тишина. Потом лязгнул засов. Изнутри.', 'Silence. Then the bolt clanked. From the inside.', W),
 ('d09', 'ФРЭНК', 'near', '— Внутрь. Быстро. И ни звука.', '— Inside. Quick. And not a sound.', 'whispering, urgent, old man'),
 ('d10', 'ИТАН', '', 'Фрэнк насыпал круг у самого порога: до засова дотягивался, не выходя из соли. Одна нога у него была примотана скотчем к куску картона.',
  'Frank had poured his circle right at the threshold: he could reach the bolt without leaving the salt. One of his legs was taped to a piece of cardboard.', 'quiet'),
 ('d11', 'ФРЭНК', '', '— Неделю назад упал на лестнице. Сюда дополз. Кулер с водой, сухари из аварийного шкафа. Днём кричал — через эту дверь не слышно.',
  '— Fell on the stairs a week ago. Crawled down here. Water cooler, crackers from the emergency cabinet. In the daytime I shouted. Nobody hears through that door.', 'hoarse, tired, old man'),
 ('d12', 'ФРЭНК', '', '— Шесть ночей держался. Седьмую одному не выдержать.', '— Held out six nights. Can\'t make it through the seventh alone.', 'hoarse, tired, old man'),
 ('d13', 'ФРЭНК', '', '— Меня теперь держит только соль. А тебя — только то, что молчишь.',
  '— Only the salt holds me now. And the only thing holding you is keeping your mouth shut.', 'hoarse, grim, old man'),
 ('d14', 'ИТАН', '', 'Из темноты за кругом позвали Фрэнка. Старческим женским голосом. Ласково.', 'From the dark beyond the circle, someone called to Frank. An old woman\'s voice. Tender.', W),
 ('d15', 'ГОЛОС', 'fake', '— Фрэнки… Сыночек…', '— Frankie… My boy…', 'tender, old woman, distant'),
 ('d16', 'ФРЭНК', '', '— Мама?..', '— Mom?..', 'quiet, almost joyful'),
 ('d17', 'ИТАН', '', 'Фрэнк потянулся на голос. К краю круга.', 'Frank reached toward the voice. Toward the edge of the circle.', W),
 ('d18', 'ГОЛОС', 'fake', '— Фрэнки, иди ко мне… Холодно тут…', '— Frankie, come to me… It\'s so cold here…', 'tender, old woman, pleading'),
 ('d19', 'ГОЛОС', 'fake', '— Сынок… Ну что же ты… Мама ждёт…', '— Son… What are you doing… Mama\'s waiting…', 'tender, old woman, sad'),
 ('d20', 'ИТАН', '', 'В шесть голос оборвался на полуслове.', 'At six, the voice broke off mid-word.', 'quiet, exhausted'),
 ('d21', 'ФРЭНК', '', '— Всё. До ночи оно спит.', '— That\'s it. It sleeps till nightfall.', 'hoarse, exhausted, old man'),
 ('d22', 'ИТАН', '', 'Я закинул его руку себе на плечо. Сорок ступенек наверх. Он не проронил ни слова.',
  'I put his arm over my shoulder. Forty steps up. He didn\'t say a word.', T),
 ('d23', 'ИТАН', '', 'Мы вышли под дождь. Ещё не светало. Но где-то за домами уже прошёл первый трамвай.',
  'We stepped out into the rain. It wasn\'t light yet. But somewhere behind the houses the first tram had already gone by.', 'quiet, calm'),
 ('d24', 'ФРЭНК', '', '— Гас?', '— Gus?', 'quiet, old man'),
 ('d25', 'ИТАН', '', 'Я покачал головой.', 'I shook my head.', 'quiet'),
 ('d26', 'ФРЭНК', '', '— Он ведь сюда ради неё и ходил. Послушать.', '— That\'s why he kept coming here, you know. To listen to her.', 'quiet, sad, old man'),
 ('d27', 'ИТАН', '', 'Фрэнк закурил.', 'Frank lit a cigarette.', 'quiet'),
 ('d28', 'ФРЭНК', '', '— Сам ведь записал: не отзывайся. А назавтра мама позвала — и отозвался. Тридцать лет как её схоронил.',
  '— Wrote it down myself: don\'t answer. And the very next night Mom called, and I answered. Buried her thirty years ago.', 'quiet, bitter, old man'),
 ('d29', 'ФРЭНК', '', '— Мне теперь до конца жизни спать в круге. А ты уходи, сынок. Пока не отозвался.',
  '— Now I sleep in a circle for the rest of my life. But you get out of here, son. Before you answer.', 'quiet, grave, old man'),
 ('d30', 'ИТАН', '', 'Я не ушёл. Лили нужны были деньги.', 'I didn\'t leave. Lily needed the money.', T),
 ('d31', 'ИТАН', '', 'Теперь каждую ночь, ровно в три, у лифта кто-то стоит и зовёт меня по имени. Голосом Лили. Я пока ни разу не ответил.',
  'Now every night, at exactly three, someone stands by the elevator and calls my name. In Lily\'s voice. So far, I haven\'t answered once.', 'quiet, slow'),
 # --- Б2: остаться на посту ---
 ('w01', 'ИТАН', '', 'Я никуда не пошёл. Это мог быть кто угодно. И что угодно.', 'I didn\'t go anywhere. It could have been anyone. Anything.', T),
 ('w02', 'ИТАН', '', 'Полтора часа я смотрел на мониторы. Тринадцатая больше не включалась.', 'For an hour and a half I watched the monitors. Thirteen didn\'t come on again.', T),
 ('w03', 'ИТАН', '', 'Где-то подо мной, в круге соли, сидел старик. А я сидел наверху и ждал шести.',
  'Somewhere beneath me, an old man sat in a circle of salt. And I sat upstairs, waiting for six.', 'quiet, guilty'),
 ('w04', 'ИТАН', '', 'В пять сорок зазвонил телефон. «Лили».', 'At five-forty my phone rang. "Lily."', 'quiet, tense'),
 ('w05', 'ИТАН', '', 'Двадцать минут до шести. Свои до утра подождут.', 'Twenty minutes to six. Your own can wait till morning.', 'whispering'),
 ('w06', 'ИТАН', '', 'Я сбросил. Оно позвонило снова. И ещё раз. Потом затихло.', 'I declined. It called again. And again. Then it went quiet.', 'quiet, tense'),
 ('w07', 'ИТАН', '', 'В шесть пришёл дневной охранник.', 'At six the day guard came in.', T),
 ('w08', 'СМЕНЩИК', '', '— Не отвечал?', '— You didn\'t answer?', 'low, wary'),
 ('w09', 'ИТАН', '', 'Мы спустились вниз вдвоём. Дверь серверной была распахнута. Из круга в коридор тянулись следы ладоней.',
  'We went down together. The server-room door was wide open. Handprints trailed from the circle out into the corridor.', 'quiet, hollow'),
 ('w10', 'ИТАН', '', 'Я открыл журнал на последней странице и дописал строчку. Своим почерком. Для того, кто придёт после меня.',
  'I opened the logbook to the last page and added a line. In my own handwriting. For whoever comes after me.', 'quiet, slow'),
 # --- смерти ---
 ('k1a', 'ИТАН', '', 'Я посмотрел в тринадцатую. Оно уже стояло лицом к камере. Будто ждало, когда я посмотрю.',
  'I looked at thirteen. It was already facing the camera. As if it had been waiting for me to look.', W),
 ('k1b', 'ИТАН', '', 'Оно сказало моё имя. И я ответил раньше, чем понял, что отвечаю.', 'It said my name. And I answered before I realized I was answering.', W),
 ('k2a', 'ИТАН', '', 'Я поднялся на седьмой. Свет горел, пахло мокрой тряпкой.', 'I went up to seven. The lights were on. It smelled of a wet rag.', 'quiet, tense'),
 ('k2b', 'ИТАН', '', 'В дверях семьсот седьмого лежал Гас. Над ним кто-то сидел.', 'Gus was lying in the doorway of seven-oh-seven. Someone was crouched over him.', W),
 ('k2c', 'ИТАН', '', 'Лампы начали гаснуть. С дальнего конца. Ко мне.', 'The lights started going out. From the far end. Toward me.', W),
 ('k3a', 'ИТАН', '', '— Гас! Держись, я сейчас поднимусь!', '— Gus! Hang on, I\'m coming up!', 'urgent, loud'),
 ('k3b', 'ГАС', 'radio', '— Спасибо, Итан.', '— Thank you, Ethan.', 'calm, warm, creepy'),
 ('k4a', 'ИТАН', '', 'Я не успел. Тот, в коридоре, обернулся. Лица у него не было. Только рот. И этот рот сказал моё имя.',
  'I wasn\'t fast enough. The one in the corridor turned around. It had no face. Only a mouth. And the mouth said my name.', W),
 ('k4b', 'ИТАН', '', 'И я ответил раньше, чем понял, что отвечаю.', 'And I answered before I realized I was answering.', W),
 ('k5a', 'ЛИЛИ', 'near', '— Вот ты где, Итан.', '— There you are, Ethan.', 'whispering, sweet, creepy'),
 ('k7a', 'ИТАН', '', 'Я открыл дверь.', 'I opened the door.', 'quiet, tense'),
 ('k7b', 'ИТАН', '', 'Фрэнк сидел в круге. Смотрел на меня и мотал головой: нет, нет, нет.', 'Frank was sitting in the circle. Looking at me and shaking his head: no, no, no.', W),
 ('k7c', 'ИТАН', '', 'А голос, который меня позвал, был у меня за спиной.', 'And the voice that had called me was right behind me.', W),
 ('k8a', 'ИТАН', '', 'Фрэнк выполз из круга. Темнота сомкнулась над ним без единого звука.', 'Frank crawled out of the circle. The dark closed over him without a sound.', W),
 ('k8b', 'ФРЭНК', 'fake', '— Итан?..', '— Ethan?..', 'quiet, old man, distant'),
 ('k8c', 'ИТАН', '', '— Фрэнк?!', '— Frank?!', 'urgent, scared'),
 ('k9a', 'ЛИЛИ', 'fake', '— Итан. Наконец-то.', '— Ethan. Finally.', 'calm, sweet, creepy'),
 ('k9b', 'ИТАН', '', 'Это был её голос. Только звучал он не из трубки. Из холла.', 'It was her voice. But it wasn\'t coming from the phone. It was coming from the lobby.', W),
 # --- смена (часы между сюжетными сценами, 23 окт): рации, обходы, странности на камерах, смерти смены ---
 ('n01', 'ИТАН', '', 'Двадцать два ноль-ноль. Вход заперт, лифт — в ночном режиме. Двенадцать этажей и я.', 'Ten p.m. The entrance is locked, the elevator is on night mode. Twelve floors and me.', T),
 ('n02', 'ИТАН', '', 'Обход. Лестница, этажи, подвал. Фонарь, ключи — и никого.', 'Rounds. Stairs, floors, basement. Flashlight, keys, and nobody.', T),
 ('n03', 'ИТАН', '', 'У серверной пахло воском. Из-под двери тянулась тёплая полоска света.', 'It smelled of wax by the server room. A warm strip of light ran out from under the door.', 'quiet, uneasy'),
 ('n04', 'ИТАН', '', 'Заперто. Ключа от серверной в связке не было.', 'Locked. There was no server-room key on the ring.', T),
 ('n05', 'ИТАН', '', 'Наверное, аварийная лампа. Я пошёл наверх.', 'Probably the emergency light. I went back up.', T),
 ('n06', 'ИТАН', '', 'Кошка у баков. Фрэнк писал про неё двадцать лет. Запишу и я.', 'A cat by the dumpsters. Frank wrote about her for twenty years. I\'ll log her too.', 'quiet, warm'),
 ('n07', 'ИТАН', '', 'На десятом кто-то оставил свет. Выключу с пульта.', 'Someone left the lights on on ten. I\'ll switch them off from the console.', T),
 ('n08', 'ГАС', 'radio', '— Охрана, это опять Гас. Чайник у тебя в будке есть? Фрэнк мне всегда оставлял.', '— Security, it\'s Gus again. Got a kettle in that booth? Frank always left me one.', 'friendly, old man'),
 ('n09', 'ИТАН', '', '— Есть. Спускайся.', '— Sure. Come on down.', 'casual'),
 ('n10', 'ГАС', 'radio', '— Не, я уж тут, наверху. Тут тихо. Хорошо слышно…', '— Nah, I\'ll stay up here. It\'s quiet. You can hear real well up here…', 'calm, dreamy, a bit odd'),
 ('n11', 'ИТАН', '', 'Что ему там слышно, я не спросил.', 'I didn\'t ask what he could hear up there.', 'quiet, uneasy'),
 ('n12', 'ИТАН', '', 'Помехи. Только в углу, у двери. Как будто там кто-то стоит.', 'Static. Just in the corner, by the door. As if someone were standing there.', 'quiet, tense'),
 ('n13', 'ИТАН', '', 'Лифт поехал сам. На пульте — никого. Наверное, датчик.', 'The elevator moved on its own. Nobody at the console. Must be a sensor.', 'quiet, tense'),
 ('n14', 'ГАС', '', '— А, новенький. Держи яблоко, с дачи.', '— Ah, the new guy. Here, have an apple. From my garden.', 'friendly, warm, old man'),
 ('n15', 'ГАС', '', '— Здание старое, всякое мерещится. Ты главное — в голову не бери.', '— Old building. You see all sorts of things. Just don\'t let it get to you.', 'kind, reassuring, old man'),
 ('n16', 'ИТАН', '', '— Спасибо. А вы давно тут?', '— Thanks. Have you been here long?', 'polite, curious'),
 ('n17', 'ГАС', '', '— Тридцать лет. Жена тут работала, на седьмом. Теперь вот я мою.', '— Thirty years. My wife worked here, on seven. Now I\'m the one mopping.', 'quiet, sad, old man'),
 ('n18', 'ИТАН', '', 'Половина третьего. Журнал всё ещё лежал закрытым.', 'Half past two. The logbook was still lying there, closed.', T),
 ('n19', 'ИТАН', '', 'На пульте появилась ещё одна кнопка. Тринадцать. Минуту назад её не было.', 'Another button had appeared on the console. Thirteen. A minute ago it wasn\'t there.', 'quiet, tense'),
 ('n20', 'ЛИЛИ', 'phone', '— Итан?.. Это ты?', '— Ethan?.. Is that you?', 'quiet, sweet, uncertain'),
 ('n21', 'ИТАН', '', 'Шаги. Уже не на камерах — в холле.', 'Footsteps. Not on the cameras anymore. In the lobby.', W),
 ('n22', 'ИТАН', '', 'Помехи сложились в лицо. Оно смотрело прямо в объектив.', 'The static took the shape of a face. It was looking straight into the lens.', W),
 ('n23', 'ИТАН', '', '— Да. Это я.', '— Yes. It\'s me.', 'quiet, relieved'),
 ('n24', 'ИТАН', '', 'Трубку я положил молча.', 'I put the phone down without a word.', T),
 # --- смена S5 (ветка «остаться в будке», 04:20–05:35) и S6 (серверная с Фрэнком, 04:30–05:58) ---
 ('n25', 'ИТАН', '', 'Четыре двадцать. Фрэнк внизу, в круге. А я здесь. До шести почти два часа.', "Four twenty. Frank's downstairs, in the circle. And I'm up here. Almost two hours till six.", T),
 ('n26', 'ГАС', 'radio', '— Итан… Спустись ко мне. Тут так хорошо слышно…', '— Ethan… Come down to me. You can hear so well up here…', 'calm, sweet, creepy'),
 ('n27', 'ИТАН', '', 'Гаса больше нет. Я видел это на тринадцатой.', "Gus is gone. I saw it on thirteen.", 'quiet, shaken'),
 ('n28', 'ИТАН', '', 'Снизу постучали. Три раза. Как просил Фрэнк. Только просил он об этом меня.', "Someone knocked downstairs. Three times. The way Frank asked. Except he asked me to do it.", 'quiet, tense'),
 ('n29', 'ИТАН', '', 'У входа стояла Лили. Под дождём, без зонта. Лили спала в трёхстах километрах отсюда.', "Lily was standing at the entrance. In the rain, no umbrella. Lily was asleep two hundred miles away.", 'quiet, tense'),
 ('n30', 'ИТАН', '', 'Я открыл. Она вошла и улыбнулась. Слишком широко.', "I opened it. She came in and smiled. Too wide.", W),
 ('n31', 'ИТАН', '', 'Свет начал гаснуть. Этаж за этажом. Сверху вниз. Ко мне.', "The lights started going out. Floor by floor. Top to bottom. Toward me.", 'quiet, tense'),
 ('n32', 'ИТАН', '', 'Голос стих. Фрэнк тяжело дышал. В серверной стоял регистратор: все камеры на одном мониторе.', "The voice faded. Frank was breathing hard. The server room had the recorder: every camera on one monitor.", T),
 ('n33', 'ФРЭНК', '', '— Смотри камеры. Всё, что не так, — записывай. Я двадцать лет так утра дожидался.', "— Watch the cameras. Anything wrong, you log it. That's how I waited for morning for twenty years.", 'old man, tired, firm'),
 ('n34', 'ФРЭНК', '', '— В помехи долго не смотри. Оно оттуда смотрит.', "— Don't stare at the static. It looks back out of it.", 'old man, low, serious'),
 ('n35', 'ФРЭНК', '', '— Если я пойду на голос — держи. Что бы я ни говорил.', "— If I go after the voice, hold me back. Whatever I say.", 'old man, quiet, scared'),
 ('n36', 'ФРЭНК', '', '— Без двадцати шесть. Держимся, парень.', "— Twenty to six. Hang in there, kid.", 'old man, tired, warm'),
 ('n37', 'ГОЛОС', 'fake', '— Фрэнки… Открой маме… Замёрзла я тут…', "— Frankie… Open up for Mom… I'm so cold out here…", 'old woman, weak, pleading'),
 # --- смена A1 (ветка «открыл → спрятался в будке», 04:00–05:45): «Лили» ходит по этажам и ищет его ---
 ('n38', 'ИТАН', '', 'Шаги ушли наверх. До шести — два часа. Я убавил яркость мониторов до самого низа и смотрел.', "The footsteps went upstairs. Two hours till six. I turned the monitors down as dark as they'd go, and watched.", W),
 ('n39', 'ЛИЛИ', 'fake', '— Итан?.. Я знаю, что ты здесь. Мне холодно. Выйди ко мне.', "— Ethan?.. I know you're here. I'm cold. Come out to me.", 'soft, sweet, whispering, uncanny'),
 ('n40', 'ИТАН', '', 'На седьмом загорелся свет. Потом на десятом. Она ходит по этажам и щёлкает выключателями. Ищет.', "The lights came on on seven. Then on ten. She's walking the floors, flipping switches. Searching.", 'quiet, tense'),
 ('n41', 'ИТАН', '', 'Зазвонил внутренний. Если сниму трубку — она услышит, где я.', "The internal phone rang. If I pick up, she'll hear where I am.", W),
 ('n42', 'ЛИЛИ', 'fake', '— Я слышу, как ты дышишь.', "— I can hear you breathing.", 'whispering, very close, playful, uncanny'),
 ('n43', 'ИТАН', '', 'Без двадцати шесть. Шаги стихли. Я не знаю, где она. И это хуже всего.', "Twenty to six. The footsteps stopped. I don't know where she is. And that's the worst part.", 'quiet, shaken'),
 # --- обучение: диспетчер охранного пульта «Щит» Вера объясняет по рации, что где (первый час смены) ---
 ('t01', 'ВЕРА', 'radio', '— Охрана «Горизонта», это пульт «Щит», диспетчер Вера. Первая смена? Давай быстро покажу, что у тебя на мониторах.', "— Horizon security, this is Shield dispatch, Vera speaking. First shift? Let me quickly show you what's on your monitors.", 'calm, professional, over the radio'),
 ('t02', 'ВЕРА', 'radio', '— Внизу — камеры здания. Нажми любую. Например, третью — лифты.', "— Along the bottom are the building's cameras. Tap one. Try three, the elevators.", 'calm, professional, over the radio'),
 ('t03', 'ВЕРА', 'radio', '— Твоя работа — замечать, что не так. Видишь табло лифта? Тринадцатый этаж. А в здании их двенадцать.', "— Your job is to notice what's wrong. See the elevator display? Floor thirteen. The building only has twelve.", 'calm, professional, over the radio'),
 ('t04', 'ВЕРА', 'radio', '— Нажми «Записать» и выбери, что это. Сейчас — «Лифт».', "— Tap Log and pick what it is. This time, Elevator.", 'calm, professional, over the radio'),
 ('t05', 'ВЕРА', 'radio', '— Вот так. Записал — и оно пропало. Пропустишь три за час — будут проблемы.', "— That's it. Once it's logged, it goes away. Miss three in an hour, and you'll be in trouble.", 'calm, professional, over the radio'),
 ('t06', 'ВЕРА', 'radio', '— Слева вверху — микрофон камеры. Прыгают столбики — значит, там звук. Его тоже записывай.', "— Top left is the camera mic. When the bars jump, there's a sound. Log that too.", 'calm, professional, over the radio'),
 ('t07', 'ВЕРА', 'radio', '— «Пульт» — это свет на этажах, вход и лифт. К десяти вход запри, лифт останови.', "— The console runs the floor lights, the entrance and the elevator. By ten, lock the entrance and stop the elevator.", 'calm, professional, over the radio'),
 ('t08', 'ВЕРА', 'radio', '— В «Журнале» — памятка и записи прежнего охранника. Почитай, пока тихо.', "— The logbook has your instructions and the previous guard's notes. Read them while it's quiet.", 'calm, professional, over the radio'),
 ('t09', 'ВЕРА', 'radio', '— И ещё. Если на камере помехи — не засматривайся. Записал — и сразу переключай. Всё, удачной смены.', "— One more thing. If a camera shows static, don't stare at it. Log it and switch right away. That's all. Have a good shift.", 'calm, professional, over the radio'),
 # --- 23 окт: обходы и разговоры (владелец: «больше сюжета и интерактива — пойти проверить, поговорить, выбор») ---
 # будка Фрэнка, 21:06: осмотр (куртка — соль, фото — Марта, ящик — телефон Фрэнка, журнал)
 ('fb00', 'ИТАН', '', 'Будка Фрэнка. Кружка с недопитым чаем, куртка на спинке стула. Будто он вышел на минуту. Неделю назад.',
  "Frank's booth. A mug of unfinished tea, the jacket on the back of the chair. As if he'd stepped out for a minute. A week ago.", T),
('fb01', 'ИТАН', '', 'Будка Фрэнка. Всё, как сказал сменщик: лампа, остывший чай, куртка на спинке стула. Будто он вышел на минуту.',
  "Frank's booth. Just like the day guard said: the lamp, the cold tea, the jacket on the back of the chair. As if he'd stepped out for a minute.", T),
 ('fb02', 'ИТАН', '', 'В кармане куртки — пачка крупной соли, наполовину пустая. И горсть соли россыпью. Зачем охраннику соль?',
  'In the jacket pocket, a pack of coarse salt, half empty. And a handful of loose salt. Why would a security guard carry salt?', 'quiet, puzzled'),
 ('fb03', 'ИТАН', '', 'Под стеклом на столе — фото. Фрэнк, старик в рабочем комбинезоне и женщина в красном платье. Её лицо стёрто, будто его тысячу раз гладили пальцем. На обороте: «Марта. Седьмой этаж. Новый год».',
  "Under the glass on the desk, a photo. Frank, an old man in work overalls, and a woman in a red dress. Her face was worn away, as if someone had stroked it with a finger a thousand times. On the back: 'Martha. Seventh floor. New Year's.'", 'quiet, slow'),
 ('fb04', 'ИТАН', '', 'В ящике — телефон Фрэнка, разряжен в ноль. Я поставил его на зарядку: вдруг полиции понадобится, кому он звонил.',
  "In the drawer, Frank's phone, completely dead. I put it on the charger, in case the police want to know who he called.", T),
 ('fb05', 'ИТАН', '', 'Журнал перевязан бечёвкой. На обложке рукой Фрэнка: «До трёх. Весь». Я отложил его. До трёх ещё далеко.',
  "The logbook was tied with string. On the cover, in Frank's hand: 'Before three. All of it.' I put it aside. Three was a long way off.", T),
 # звонок дневного охранника, 22:00: темы на выбор
 ('dg01', 'ИТАН', '', 'В десять зазвонил мой телефон. Номер незнакомый.', 'At ten my phone rang. An unknown number.', T),
 ('dg02', 'СМЕНЩИК', 'phone', '— Это дневной. В агентстве твой номер дали. Ну как ты там, новенький? Живой?',
  "— It's the day guard. The agency gave me your number. So how's it going, new guy? Still alive?", 'gruff, trying to sound casual'),
 ('dg03', 'ИТАН', '', '— Что на самом деле случилось с Фрэнком?', '— What really happened to Frank?', 'quiet, serious'),
 ('dg04', 'СМЕНЩИК', 'phone', '— Не знаю. Последнюю неделю он был сам не свой. Сыпал соль по углам, у дверей, на порог будки. Я думал — от крыс.',
  "— I don't know. His last week he wasn't himself. Poured salt in the corners, by the doors, on the booth threshold. I figured it was for rats.", 'gruff, uneasy'),
 ('dg05', 'ИТАН', '', '— Зачем ты стучал в стекло, когда уходил?', '— Why did you knock on the glass when you left?', 'curious'),
 ('dg06', 'СМЕНЩИК', 'phone', '— Чтоб ты запомнил. Три стука — это я. Утром приду — постучу так же. Фрэнк говорил: оно не стучит. Оно зовёт.',
  "— So you'd remember. Three knocks, that's me. I'll knock the same way in the morning. Frank used to say: it doesn't knock. It calls.", 'low, serious'),
 ('dg07', 'ИТАН', '', '— Оно — это кто?', "— 'It'? What's 'it'?", 'uneasy'),
 ('dg08', 'СМЕНЩИК', 'phone', '— Я в эти сказки не верю. И ты не верь. Сиди до шести, дверь никому не открывай, на имя не отзывайся. Вот и вся работа.',
  "— I don't believe in those fairy tales. Neither should you. Sit tight till six, don't open the door for anyone, don't answer to your name. That's the whole job.", 'gruff, a little too fast'),
 ('dg09', 'ИТАН', '', '— В здании ещё кто-нибудь есть?', '— Is anyone else in the building?', 'casual'),
 ('dg10', 'СМЕНЩИК', 'phone', '— Гас, уборщик. Седьмой этаж моет, всю ночь там. Тридцать лет здесь. Ты с ним помягче — он вдовец.',
  "— Gus, the cleaner. Mops the seventh floor, he's up there all night. Thirty years here. Go easy on him, he's a widower.", 'gruff, softer'),
 ('dg11', 'ИТАН', '', '— Ладно. До утра.', '— Okay. See you in the morning.', 'casual'),
 ('dg12', 'СМЕНЩИК', 'phone', '— До утра. Три стука. Запомнил?', '— See you. Three knocks. Got it?', 'low, serious'),
 # обход, подвал, 22:05: дверь серверной — постучать, посветить под дверь, позвать
 ('bm01', 'ИТАН', '', 'Я постучал. Тишина. Потом изнутри — три удара. Медленных, тяжёлых. Будто кто-то берёг силы.',
  'I knocked. Silence. Then, from inside — three knocks. Slow, heavy. As if someone were saving their strength.', W),
 ('bm02', 'ИТАН', '', 'По всему порогу, с той стороны, — белая полоса. Соль. Её насыпали изнутри.',
  'Along the whole threshold, on the other side — a white line. Salt. Someone had poured it from the inside.', 'quiet, uneasy'),
 ('bm03', 'ИТАН', '', '— Эй! Есть там кто?', '— Hey! Anyone in there?', 'calling out, nervous'),
 ('bm04', 'ИТАН', '', 'Ни звука. Только свет под дверью дрогнул, будто кто-то прошёл мимо щели.',
  'Not a sound. Only the light under the door flickered, as if someone had walked past the gap.', W),
 ('bm05', 'ИТАН', '', 'Наверное, трубы. Я повторял себе это всю дорогу наверх.', 'Probably the pipes. I kept telling myself that all the way upstairs.', T),
 # Гас на седьмом, 01:00: темы (Марта, Фрэнк, кто зовёт, обещание)
 ('gs01', 'ИТАН', '', '— Женщина на фото у Фрэнка, в красном платье, — это Марта?', "— The woman in Frank's photo, in the red dress — is that Martha?", 'gentle'),
 ('gs02', 'ГАС', '', '— Марта. Наш последний Новый год. Через месяц её не стало. Я её лицо на той фотке до дыр затёр.',
  "— Martha. Our last New Year's. A month later she was gone. I've rubbed her face on that photo half away.", 'warm, sad, old man'),
 ('gs03', 'ИТАН', '', '— Ваша жена тоже здесь работала?', '— Did your wife work here too?', 'gentle'),
 ('gs04', 'ГАС', '', '— Марта. Бухгалтер, седьмой этаж, семьсот седьмой кабинет. Тридцать лет мы тут вместе. Теперь я один.',
  '— Martha. Bookkeeper, seventh floor, office seven-oh-seven. Thirty years we were here together. Now it\'s just me.', 'warm, sad, old man'),
 ('gs05', 'ИТАН', '', '— Фрэнк перед тем, как пропасть, что-нибудь говорил?', '— Did Frank say anything before he disappeared?', 'quiet, serious'),
 ('gs06', 'ГАС', '', '— Всё спрашивал, не зовут ли меня ночами. Я сказал — зовут. Он побелел весь. Соли мне в карман насыпал. Чудак.',
  "— Kept asking if anyone calls me at night. I told him they do. He went white as a sheet. Poured salt in my pocket. Odd fellow.", 'old man, amused but uneasy'),
 ('gs07', 'ИТАН', '', '— Кто вас зовёт?', '— Who calls you?', 'careful'),
 ('gs08', 'ГАС', '', '— Марта. С седьмого, из семьсот седьмого. Ты не думай, я не сумасшедший. Я не отвечаю. Я просто прихожу послушать.',
  "— Martha. From seven, from seven-oh-seven. Don't think I'm crazy. I don't answer. I just come to listen.", 'quiet, tender, old man'),
 ('gs09', 'ИТАН', '', '— Гас. Что бы она ни говорила — не отвечайте. Обещайте.', "— Gus. Whatever she says, don't answer. Promise me.", 'quiet, urgent'),
 ('gs10', 'ГАС', '', '— Тридцать лет она меня звала: то обедать, то домой… Ладно, сынок. Обещаю.',
  '— Thirty years she called me: to lunch, to come home… All right, son. I promise.', 'old man, moved, quiet'),
 # звонок Лили (настоящей), 01:15: она в общаге, за триста километров
 ('ly01', 'ИТАН', '', 'В четверть второго позвонила Лили.', 'At a quarter past one, Lily called.', 'quiet, warm'),
 ('ly02', 'ЛИЛИ', 'phone', '— Не спишь? Я тоже. Завтра экзамен в восемь, а я сижу в общаге на подоконнике и ничего не помню.',
  "— You're up? Me too. Exam at eight tomorrow, and I'm sitting on the windowsill in the dorm and can't remember a thing.", 'warm, tired, teasing'),
 ('ly03', 'ИТАН', '', '— Как там Бублик?', "— How's Biscuit?", 'warm'),
 ('ly04', 'ЛИЛИ', 'phone', '— Мама пишет — гоняет курьеров. Твой свитер утащил в будку и спит на нём.',
  '— Mom says he chases the delivery guys. He dragged your sweater into his doghouse and sleeps on it.', 'warm, laughing softly'),
 ('ly05', 'ИТАН', '', '— Ты сейчас в общаге?', "— You're at the dorm right now?", 'casual'),
 ('ly06', 'ЛИЛИ', 'phone', '— А где ж ещё? В трёхстах километрах от тебя, балбес. Соседка храпит — я в коридоре.',
  "— Where else? Two hundred miles from you, dummy. My roommate snores, so I'm out in the hallway.", 'teasing, warm'),
 ('ly07', 'ИТАН', '', '— Тут… странно. Свет на этажах сам загорается.', "— It's… weird here. The lights on the floors come on by themselves.", 'hesitant'),
 ('ly08', 'ЛИЛИ', 'phone', '— Не пугай меня. Обещай, что утром позвонишь. Первым делом. И не геройствуй там.',
  "— Don't scare me. Promise you'll call in the morning. First thing. And don't play the hero.", 'worried, serious'),
 ('ly09', 'ИТАН', '', '— Спи давай. Всё сдашь.', "— Go to sleep. You'll ace it.", 'warm'),
 ('ly10', 'ЛИЛИ', 'phone', '— Ага. Люблю тебя, балбес. Спокойной ночи.', '— Yeah. Love you, dummy. Good night.', 'warm, sleepy'),
 # телефон Фрэнка звонит в ящике (если поставил на зарядку), 02:20: «Мама»
 ('fp01', 'ИТАН', '', 'Телефон Фрэнка звонил одиннадцать раз. Потом пришло сообщение: «Фрэнки, сынок, спустись ко мне. Я внизу».',
  "Frank's phone rang eleven times. Then a text came in: 'Frankie, son, come down to me. I'm downstairs.'", W),
 ('fp02', 'ИТАН', '', 'Я сбросил. Руки тряслись. Кто звонит старику в два часа ночи — и зовёт его вниз?',
  'I hung up. My hands were shaking. Who calls an old man at two in the morning and asks him to come downstairs?', W),
 ('fp03', 'ИТАН', '', '— Алло?.. В трубке кто-то вдохнул. С облегчением. Будто долго ждал.',
  '— Hello?.. Someone on the line drew a breath. With relief. As if they had been waiting a long time.', W),
 # кадры с условием: что узнал раньше — то и вспоминается
 ('al01', 'ИТАН', '', 'Он обещал мне. Но это был голос Марты.', "He'd promised me. But it was Martha's voice.", 'quiet, broken'),
 ('al02', 'ИТАН', '', 'Значит, это мама звала его вниз. «Фрэнки, сынок…» — как в том сообщении на его телефоне.',
  "So it was his mom calling him downstairs. 'Frankie, son…' — just like the text on his phone.", 'quiet, uneasy'),
 ('al03', 'ИТАН', '', 'Соль. Как в кармане его куртки.', 'Salt. Like in his jacket pocket.', 'quiet, slow'),
 ('al04', 'ИТАН', '', 'Вот кто стучал мне из-за двери серверной в десять вечера. Оно не стучит.',
  'So that was who knocked back at me from behind the server room door at ten. It doesn\'t knock.', 'quiet, realization'),
 # --- 04:30, серверная: осмотр комнаты и разговор с Фрэнком до шести (обход + разговор) ---
 ('sv01', 'ИТАН', '', 'Круг из крупной соли, в палец толщиной. В двух местах просыпан и насыпан заново — там, где он выползал за водой.',
  'A ring of coarse salt, a finger thick. Broken and poured again in two places — where he crawled out for water.', T),
 ('sv02', 'ИТАН', '', 'Кулер пустой на треть. Сухарей — одна пачка, последняя. Шесть ночей на этом.',
  'The cooler is a third empty. One pack of crackers left, the last. Six nights on this.', T),
 ('sv03', 'ИТАН', '', 'На стойке — листы скотчем. Один почерк, разные ночи: «Не зови меня». «Стучи три раза». «Оно говорит маминым голосом».',
  'Sheets taped to the rack. One handwriting, different nights: \'Don\'t call me.\' \'Knock three times.\' \'It speaks in my mother\'s voice.\'', R),
 ('sv05', 'ИТАН', '', '— Это правда была… она?', '— Was it really… her?', 'quiet, careful'),
 ('sv06', 'ФРЭНК', '', '— Голос — её. До последней интонации, как звала обедать. Только мама умерла в девяносто шестом, сынок. Это не она.',
  '— The voice is hers. Down to the last note, the way she called me to dinner. But my mother died in ninety-six, son. It\'s not her.', 'hoarse, tired, firm'),
 ('sv07', 'ИТАН', '', '— Гас сказал, его тоже зовут. Марта.', '— Gus said he gets called too. Martha.', T),
 ('sv08', 'ФРЭНК', '', '— Знаю. Он тридцать лет ходит на седьмой её слушать. Его оно не трогает — он не отвечает. Просто слушает. Так тоже можно.',
  '— I know. Thirty years he\'s been going up to seven to listen to her. It doesn\'t touch him — he never answers. He just listens. That\'s a way to live, too.', 'hoarse, tired'),
 ('sv09', 'ИТАН', '', '— Почему соль?', '— Why salt?', T),
 ('sv10', 'ФРЭНК', '', '— Не знаю, почему. Знаю, что работает. Отец так делал, дед так делал. Пока круг цел — оно только говорит.',
  '— I don\'t know why. I know it works. My father did it, his father did it. As long as the ring holds, it can only talk.', 'hoarse, tired'),
 ('sv11', 'ИТАН', '', '— Я посижу с вами до шести.', '— I\'ll sit with you till six.', T),
 ('sv12', 'ФРЭНК', '', '— Посиди. Только если позовут — молчи. Даже если моим голосом.', '— Sit. But if they call — not a word. Even in my voice.', 'hoarse, quiet'),
 # --- голосовые звуки (без слов; плач — звуковой эффект) ---
 ('ch_katya', 'ЛИЛИ', 'muffle', '(плачет)', '(crying)', 'sobbing quietly'),
 ('ch_whisper', 'ЛИЛИ', 'fake', '— Итан…', '— Ethan…', 'whispering, distant, creepy'),
]
out = {k: {'who': w, 'fx': fx, 'ru': ru, 'en': en, 'tag': tag} for k, w, fx, ru, en, tag in L}
assert len(out) == len(L), 'дубли ключей'
json.dump(out, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'lines.json'), 'w'), ensure_ascii=False, indent=1)
print(len(out), 'реплик', sum(len(x[3]) for x in L), 'симв. RU', sum(len(x[4]) for x in L), 'симв. EN')
